actions.script:
const probe = (name, parameters) => {
    ec.message.pushErrors()
    try {
        const out = Object.assign({}, ec.service.sync().name(name).parameters(parameters).requireNewTransaction(true).call() || {})
        out.errors = ec.message.getErrorsString()
        return out
    } catch (error) {
        return {errors: String(error.message || error)}
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
const answer = probe('mantle.product.StoreMerchandisingServices.get#StoreCategories',
    {productStoreId: productStoreId, productCategoryId: productCategoryId || null})
Object.assign(answer, {productStoreId, canMove: !!commerce.capabilities.merchandise, storeOptions: commerce.storeOptions || []})
ec.web.sendJsonResponse(answer)

const probe = (name, parameters) => {
    ec.message.pushErrors()
    try {
        const out = Object.assign({}, ec.service.sync().name(name).parameters(parameters).requireNewTransaction(true).call() || {})
        out.errors = ec.message.getErrorsString()
        return out
    } catch (error) {
        return {errors: String(error.message || error)}
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
const flag = value => value === true || value === 'true'
ec.web.sendJsonResponse(probe('mantle.product.StoreMerchandisingServices.move#StoreCategory', {
    productStoreId, productCategoryId, toParentCategoryId: toParentCategoryId || null,
    fromParentCategoryId: fromParentCategoryId || null, direction: direction || null,
    beforeCategoryId: beforeCategoryId || null, previewOnly: flag(previewOnly), confirmShared: flag(confirmShared)}))
